/**
 * 똥(장애물) 설정
 *
 * 모든 똥 오브젝트(일반, 금똥, 다이아똥, 토파즈똥)의 크기, 속도, 히트박스 등을 관리합니다.
 * 게임 밸런싱 조정 시 이 파일만 수정하면 됩니다.
 */

export interface PoopConfig {
  /** 일반 똥 설정 */
  normal: {
    /** 기본 낙하 속도 */
    baseSpeed: number;
    /** 난이도 레벨당 속도 증가량 */
    speedIncrement: number;
    /** 일반 똥 크기 */
    size: {
      /** 기본 크기 */
      normal: number;
      /** EXTREME 난이도 크기 */
      extreme: number;
    };
    /** 크리스마스 특수 똥 크기 (코, 리본, 산타, 수염) */
    specialSize: {
      /** 기본 크기 */
      normal: number;
      /** EXTREME 난이도 크기 */
      extreme: number;
    };
    /** 히트박스 크기 */
    hitbox: {
      /** 기본 히트박스 */
      normal: number;
      /** EXTREME 난이도 히트박스 */
      extreme: number;
    };
  };
  /** 금똥 설정 */
  gold: {
    /** 기본 낙하 속도 */
    baseSpeed: number;
    /** 일반 똥 대비 속도 조정량 (양수: 느림, 음수: 빠름) */
    speedReduction: number;
    /** 표시 크기 */
    size: number;
    /** 히트박스 크기 (수집하기 쉽게 조금 넉넉) */
    hitbox: number;
    /** 렌더링 깊이 (다른 오브젝트 위에 표시) */
